+static void sparx5_rr_nexthop_group_put(struct sparx5 *sparx5,
+					struct sparx5_rr_nexthop_group *nh_grp)
+{
+	sparx5_rr_nh_grp_arp_tbl_grp_clear(sparx5, nh_grp);
+	sparx5_rr_nexthop_group_info_deinit(sparx5, nh_grp);
