+	case RTN_MULTICAST:
+		return SPARX5_RR_FIB_TYPE_MULTICAST;
+	case RTN_BLACKHOLE:
+		return SPARX5_RR_FIB_TYPE_BLACKHOLE;
+	case RTN_PROHIBIT:
+		return SPARX5_RR_FIB_TYPE_PROHIBIT;
+	case RTN_UNREACHABLE:
