+		}
+
+		err = submit_bio_wait(bio);
+		bio_put(bio);
+		if (err)
+			goto out;
+
+		ffs_mark_subrange_uptodate(folio, off, PAGE_SIZE);
+
+	}
+
+out:
+		if (get_dn)
+			f2fs_put_dnode(&dn);
